import {CATEGORIES,distance,validatePoint,analyze,explanation} from './core.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>[{id:'A',name:'中关村周边 · 示例',lon:116.31,lat:39.98},{id:'B',name:'国贸周边 · 示例',lon:116.45,lat:39.91},{id:'C',name:'三里屯周边 · 示例',lon:116.45,lat:39.94}];
let state={points:initial(),active:0,evidencePoint:0,category:'coffee',limit:30,results:[],ready:false,taskStart:null,taskEnd:null},pois=[],roads=[],meta=null,view={lon:116.39,lat:39.955,zoom:11},drag=null,suppressClick=false;
const canvas=$('map'),ctx=canvas.getContext('2d');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function project(lon,lat){const size=256*2**view.zoom;return[(lon+180)/360*size,(1-Math.log(Math.tan(lat*Math.PI/180)+1/Math.cos(lat*Math.PI/180))/Math.PI)/2*size];}
function unproject(x,y){const size=256*2**view.zoom;return{x:x/size*360-180,y:Math.atan(Math.sinh(Math.PI*(1-2*y/size)))*180/Math.PI};}
function xy(lon,lat){const p=project(lon,lat),c=project(view.lon,view.lat);return[p[0]-c[0]+canvas.clientWidth/2,p[1]-c[1]+canvas.clientHeight/2];}
function at(x,y){const c=project(view.lon,view.lat),p=unproject(c[0]+x-canvas.clientWidth/2,c[1]+y-canvas.clientHeight/2);return{lon:p.x,lat:p.y};}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').hidden=true,3600);}
function drawMap(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;const dpr=window.devicePixelRatio||1;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#102b3a';ctx.fillRect(0,0,w,h);
 ctx.strokeStyle='#17394b';ctx.lineWidth=1;for(let x=0;x<w;x+=48){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}for(let y=0;y<h;y+=48){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}
 for(const road of roads){const coords=road.geometry.coordinates;ctx.beginPath();for(let i=0;i<coords.length;i++){const [x,y]=xy(...coords[i]);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.strokeStyle=['motorway','trunk','primary'].includes(road.properties.kind)?'#3a6074':'#274a5d';ctx.lineWidth=['motorway','trunk'].includes(road.properties.kind)?2:1;ctx.stroke();}
 for(const p of pois){if(!p.included||!CATEGORIES[p.category])continue;const [x,y]=xy(p.lon,p.lat);if(x<-4||x>w+4||y<-4||y>h+4)continue;ctx.fillStyle=CATEGORIES[p.category].color;ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(x,y,view.zoom>=13?3:2,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
 state.points.forEach((p,i)=>{const [x,y]=xy(p.lon,p.lat);const mPerPx=156543.03392804097*Math.cos(p.lat*Math.PI/180)/2**view.zoom;ctx.beginPath();ctx.arc(x,y,1000/mPerPx,0,2*Math.PI);ctx.fillStyle=i===state.active?'#22d3c51a':'#cfe5ef09';ctx.fill();ctx.strokeStyle=i===state.active?'#22d3c5':'#88a6b7';ctx.setLineDash([4,4]);ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=i===state.active?'#22d3c5':'#e5eff4';ctx.beginPath();ctx.arc(x,y,14,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#0b2331';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#0b2331';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(p.id,x,y);});
 const mpp=156543.03392804097*Math.cos(view.lat*Math.PI/180)/2**view.zoom;const meters=100*mpp;const unit=meters>1000?`${(meters/1000).toFixed(1)} km`:`${Math.round(meters)} m`;$('scale').style.width='100px';$('scale').textContent=unit;
}
function fit(){const xs=state.points.map(p=>p.lon),ys=state.points.map(p=>p.lat);view.lon=(Math.min(...xs)+Math.max(...xs))/2;view.lat=(Math.min(...ys)+Math.max(...ys))/2;view.zoom=12;while(view.zoom>8){const screen=state.points.map(p=>xy(p.lon,p.lat));if(screen.every(([x,y])=>x>55&&x<canvas.clientWidth-55&&y>55&&y<canvas.clientHeight-55))break;view.zoom--;}drawMap();}
function fillCoordinate(){const p=state.points[state.active];$('point-name').value=p.name;$('longitude').value=p.lon.toFixed(6);$('latitude').value=p.lat.toFixed(6);$('map-hint').textContent=`点击地图设置候选点 ${p.id} · 拖动平移`;$('point-error').textContent='';}
function renderPoints(){const selected=$('preferred').value;$('candidate-list').innerHTML=state.points.map((p,i)=>`<button class="candidate ${i===state.active?'active':''}" data-point="${i}" aria-pressed="${i===state.active}"><span class="point-badge">${p.id}</span><span class="candidate-name">${esc(p.name)}<small>${p.lon.toFixed(3)}, ${p.lat.toFixed(3)}</small></span></button>`).join('');$('evidence-point').innerHTML=state.points.map((p,i)=>`<option value="${i}">${p.id} · ${esc(p.name)}</option>`).join('');$('evidence-point').value=state.evidencePoint;$('preferred').innerHTML='<option value="">请选择候选区域</option>'+state.points.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.name)}</option>`).join('');$('preferred').value=selected;fillCoordinate();}
function renderComparison(){const rs=state.results;let html='<div class="table-wrapper"><table><thead><tr><th>1 km 内收录</th>'+state.points.map(p=>`<th><span class="point-badge">${p.id}</span><span>${esc(p.name.split(' · ')[0])}</span></th>`).join('')+'</tr></thead><tbody>';
 for(const [k,c] of Object.entries(CATEGORIES))html+=`<tr><th>${c.label}</th>`+rs.map((r,i)=>`<td><button data-inspect="${i}" data-category="${k}" aria-label="查看 ${r.point.id} 的${c.label}依据">${r.counts[k]}</button>${r.counts[k]===0?'<span class="no-record">本数据未收录</span>':''}</td>`).join('')+'</tr>';
 html+='<tr><th>最近地铁入口<small class="no-record">3 km 内 · 直线</small></th>'+rs.map(r=>`<td>${r.nearest?`<a href="https://www.openstreetmap.org/${r.nearest.id}" target="_blank" rel="noopener" aria-label="查看 ${r.point.id} 最近地铁入口源记录">${Math.round(r.nearest.distance)} m</a>`:'—'}${!r.nearest?'<span class="no-record">未找到记录</span>':''}</td>`).join('')+'</tr><tr><th>未计入的记录</th>'+rs.map((r,i)=>`<td><button data-inspect="${i}" data-category="excluded">${r.excluded.length}</button></td>`).join('')+'</tr></tbody></table></div><div class="quality-notice">这些数字描述冻结数据的收录情况。0 不表示现实中不存在；咖啡类别、营业状态与覆盖完整性仍待独立核验。</div>';$('comparison').innerHTML=html;}
const reasonText={coffee_category_unverified:'咖啡类别待确认',no_explicit_coffee_tag:'茶饮/其他饮品标签',business_object_level_requires_review:'百货对象层级待核验',not_in_primary_categories:'公司对象，不计办公建筑',geometry_unusable:'几何不可用',possible_duplicate_unresolved:'疑似重复待确认',shop_entrance_not_second_venue:'门店入口，不作为第二家店',same_name_point_within_matching_polygon:'节点与设施面重复',entrance_stop_position_conflict:'入口与站点标签冲突',source_indicates_inactive:'来源提示停用'};
function renderEvidence(){const r=state.results[state.evidencePoint];if(!r)return;const cats={...CATEGORIES,excluded:{label:'未计入'}};$('category-tabs').innerHTML=Object.entries(cats).map(([k,c])=>`<button data-evidence-category="${k}" class="${k===state.category?'active':''}" aria-pressed="${k===state.category}">${c.label}</button>`).join('');const rows=state.category==='excluded'?r.excluded:r.buckets[state.category];$('evidence-summary').textContent=`${r.point.id} · ${r.point.name} / 1 km 内 ${rows.length} 条 · 点击名称查看 OSM 源对象`;
 $('evidence-list').innerHTML=rows.length?rows.slice(0,state.limit).map(p=>`<div class="poi-row"><a href="https://www.openstreetmap.org/${p.id}" target="_blank" rel="noopener">${esc(p.name)}<small>${state.category==='excluded'?esc(reasonText[p.reason]||p.reason):esc(p.id)}</small></a><strong>${Math.round(p.distance)} m</strong></div>`).join(''):'<div class="empty-evidence">这个窗口内没有收录符合当前规则的记录。请先检查数据覆盖，再判断真实环境。</div>';$('show-more').hidden=rows.length<=state.limit;
 $('summary-text').textContent=explanation(r);
}
function update(){state.results=state.points.map(p=>analyze(p,pois));$('preferred').value='';for(const id of ['reason-one','reason-two','risk'])$(id).value='';$('export-status').textContent='结论由你判断，系统不自动排名。';renderPoints();renderComparison();renderEvidence();drawMap();if(state.taskStart){state.taskStart=null;state.taskEnd=null;$('timer').textContent='候选点已更改，原计时和旧结论已清空。请重新开始任务。';$('start-task').disabled=false;}}
function setPoint(point){validatePoint(point);if(point.lon<116.10||point.lon>116.75||point.lat<39.65||point.lat>40.18)throw new Error('本版仅支持北京城区研究窗口：经度 116.10～116.75，纬度 39.65～40.18。');state.points[state.active]={...state.points[state.active],...point};state.evidencePoint=state.active;state.limit=30;update();toast('候选点已更新，三点比较已重新计算');}
$('candidate-list').addEventListener('click',e=>{const b=e.target.closest('[data-point]');if(!b)return;state.active=Number(b.dataset.point);state.evidencePoint=state.active;state.limit=30;renderPoints();renderEvidence();drawMap();});
$('comparison').addEventListener('click',e=>{const b=e.target.closest('[data-inspect]');if(!b)return;state.evidencePoint=Number(b.dataset.inspect);state.category=b.dataset.category;state.limit=30;$('evidence-point').value=state.evidencePoint;renderEvidence();});
$('evidence-point').addEventListener('change',()=>{state.evidencePoint=Number($('evidence-point').value);state.limit=30;renderEvidence();});$('category-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-evidence-category]');if(!b)return;state.category=b.dataset.evidenceCategory;state.limit=30;renderEvidence();});$('show-more').onclick=()=>{state.limit+=30;renderEvidence();};
$('coordinate-form').onsubmit=e=>{e.preventDefault();try{setPoint({name:$('point-name').value.trim(),lon:Number($('longitude').value),lat:Number($('latitude').value)});}catch(err){$('point-error').textContent=err.message;}};
$('restore').onclick=()=>{if(!state.ready)return;state.points=initial();state.active=0;state.evidencePoint=0;state.category='coffee';state.limit=30;update();fit();toast('已恢复三个示例区域');};$('zoom-in').onclick=()=>{view.zoom=clamp(view.zoom+1,9,16);drawMap();};$('zoom-out').onclick=()=>{view.zoom=clamp(view.zoom-1,9,16);drawMap();};$('fit-map').onclick=fit;
canvas.addEventListener('pointerdown',e=>{if(!state.ready)return;const rect=canvas.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX-rect.left,y:e.clientY-rect.top,view:{...view},moved:false};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const rect=canvas.getBoundingClientRect(),dx=e.clientX-rect.left-drag.x,dy=e.clientY-rect.top-drag.y;if(Math.hypot(dx,dy)>5)drag.moved=true;if(drag.moved){const c=project(drag.view.lon,drag.view.lat),p=unproject(c[0]-dx,c[1]-dy);view.lon=clamp(p.x,115.8,117);view.lat=clamp(p.y,39.5,40.3);drawMap();}});
canvas.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;canvas.releasePointerCapture(e.pointerId);if(!d.moved){const p=at(d.x,d.y);try{setPoint({name:`候选区域 ${state.points[state.active].id}`,lon:Number(p.lon.toFixed(6)),lat:Number(p.lat.toFixed(6))});}catch(err){$('point-error').textContent=err.message;toast(err.message);}}});canvas.addEventListener('pointercancel',()=>drag=null);
canvas.addEventListener('wheel',e=>{e.preventDefault();view.zoom=clamp(view.zoom+(e.deltaY<0?.5:-.5),9,16);drawMap();},{passive:false});canvas.addEventListener('keydown',e=>{if(['+','=','-'].includes(e.key)){view.zoom=clamp(view.zoom+(e.key==='-'?-1:1),9,16);drawMap();e.preventDefault();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const shift=.01*2**(12-view.zoom);if(e.key==='ArrowLeft')view.lon-=shift;if(e.key==='ArrowRight')view.lon+=shift;if(e.key==='ArrowUp')view.lat+=shift;if(e.key==='ArrowDown')view.lat-=shift;drawMap();e.preventDefault();}});
new ResizeObserver(drawMap).observe(canvas);
function methodHTML(){return `<p>面向咖啡门店候选区域初筛，将周边设施查询、同口径比较、依据核对与报告整理串成一个工作流程。输出供实地考察使用；客流、租金和盈利需结合其他资料判断。</p><h3>同一份数据、明确的统计口径</h3><ul><li>OSM 北京快照：${esc(meta.sourceTimestamp)}；清洗规则 strict-v0.2。</li><li>咖啡：只纳入明确 coffee / coffee_shop 餐饮标签的候选记录；cafe-only 等待确认，不能解释为完整竞品数量。</li><li>办公：只统计办公建筑，不混合楼内公司对象。</li><li>购物中心：统计 shop=mall；百货类别因对象层级待核验，单独保留而不计入。</li><li>地铁：统计出入口，排除站点标签冲突。最近入口为 3 km 搜索范围内的直线距离，不是步行时间。</li><li>1 km 采用 WGS84 椭球测地距离；面状设施采用面内代表点。</li></ul><h3>分析范围</h3><p>示例是区域分析中心，不是待租铺位。研究窗口为经度116.10～116.75、纬度39.65～40.18。路网是同一快照提取的主要道路，非实时底图。几何缺失、未确认类别、疑似重复等记录不参与主指标。统计反映本快照内符合规则的记录；未收录不等于现实不存在，实际营业与设施开放情况应在考察时核实。</p><h3>任务流程</h3><p>一次任务输出三点指标对照、优先考察区域、两条依据和一项待核实风险。可记录从查看、核对到判断与填写结论的完整耗时，并随报告保存。</p><h3>使用与导出</h3><p>点击地图或填写坐标修改区域；点击比较表中的数量查看源记录。填写结论后可下载 Markdown 报告，JSON 导出包含三点指标、依据记录ID、数据版本、规则和计时信息。所有输入只在当前页面内处理，不上传个人结论，刷新会清空。</p><p>已纳入 ${Object.entries(meta.includedCounts).map(([k,n])=>`${esc(CATEGORIES[k]?.label||k)} ${n}`).join(' / ')}。数据校验值：</p><code>${esc(meta.dataSha256)}</code><p><a href="data/LICENSE.txt" target="_blank" rel="noopener">© OpenStreetMap contributors / ODbL 1.0</a> · <a href="data/meta.json" target="_blank" rel="noopener">数据版本清单</a></p>`;}
$('data-info').onclick=()=>{if(!meta)return;$('method-content').innerHTML=methodHTML();$('method-dialog').showModal();};$('close-dialog').onclick=()=>$('method-dialog').close();$('method-dialog').addEventListener('click',e=>{if(e.target===$('method-dialog'))$('method-dialog').close();});
$('start-task').onclick=()=>{state.taskStart=Date.now();state.taskEnd=null;$('start-task').disabled=true;toast('完整任务计时已开始，请核对三个候选点并填写结论');};setInterval(()=>{if(!state.taskStart)return;const seconds=Math.floor(((state.taskEnd||Date.now())-state.taskStart)/1000);$('timer').textContent=`${state.taskEnd?'已提交':'任务进行中'} · ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}${seconds>=1500?' · 已超过 25 分钟测试上限':''}`;},1000);
for(const id of ['preferred','reason-one','reason-two','risk'])$(id).addEventListener('input',()=>{if(state.taskEnd){state.taskEnd=null;$('export-status').textContent='结论已修改，计时继续到下次提交。';}});
function payload(){return{product:'GeoInsight',status:'portfolio_mvp',exportedAt:new Date().toISOString(),dataset:{id:meta.datasetId,sourceTimestamp:meta.sourceTimestamp,ruleVersion:meta.version,sha256:meta.dataSha256,license:meta.license,attribution:meta.attribution},radiusMeters:1000,nearestTransitRadiusMeters:3000,distanceMethod:'WGS84 Vincenty inverse, straight line',candidates:state.results.map(r=>({point:r.point,counts:r.counts,nearestSubwayMeters:r.nearest?.distance??null,nearestSubwayId:r.nearest?.id??null,evidenceIds:Object.fromEntries(Object.entries(r.buckets).map(([k,v])=>[k,v.map(p=>p.id)])),excludedIds:r.excluded.map(p=>p.id)})),decision:{preferred:$('preferred').value||null,reasonOne:$('reason-one').value.trim(),reasonTwo:$('reason-two').value.trim(),risk:$('risk').value.trim()},task:{condition:'system',startedAt:state.taskStart?new Date(state.taskStart).toISOString():null,submittedAt:state.taskEnd?new Date(state.taskEnd).toISOString():null,elapsedSeconds:state.taskStart?((state.taskEnd||Date.now())-state.taskStart)/1000:null,timeout:!!(state.taskStart&&((state.taskEnd||Date.now())-state.taskStart)>1500000),quality:'not_independently_scored'},limitations:['指标基于指定OSM快照与分类规则','未收录不等于现实不存在','实际营业、客流和租金需实地核实','初筛用于安排考察优先级']};}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export-json').onclick=()=>{if(!state.ready)return;download(JSON.stringify(payload(),null,2),'GeoInsight-区域分析.json','application/json');toast('分析数据已导出');};
$('conclusion-form').onsubmit=e=>{e.preventDefault();if(!state.ready)return;const texts=['reason-one','reason-two','risk'];if(texts.some(id=>$(id).value.trim().length<8)){$('export-status').textContent='请填写两条依据和一项风险，每项至少 8 个有效字符。';return;}if(state.taskStart&&!state.taskEnd)state.taskEnd=Date.now();const p=payload();let md=`# GeoInsight 候选区域初筛报告\n\n数据：${meta.datasetId} / ${meta.sourceTimestamp} / ${meta.version}\n\n统计半径1km；地铁最近入口搜索半径3km；WGS84直线距离。\n\n|指标|${state.points.map(x=>x.id+' '+x.name.replaceAll('|','/')).join('|')}|\n|---|---:|---:|---:|\n`;for(const[k,c]of Object.entries(CATEGORIES))md+=`|${c.label}|${state.results.map(r=>r.counts[k]).join('|')}|\n`;md+=`|最近收录地铁入口(m)|${state.results.map(r=>r.nearest?Math.round(r.nearest.distance):'未发现记录').join('|')}|\n\n## 我的初筛结论\n\n优先考察：${p.decision.preferred}\n\n依据一：${p.decision.reasonOne}\n\n依据二：${p.decision.reasonTwo}\n\n待核实风险：${p.decision.risk}\n\n## 候选点与追溯\n\n`;for(const r of state.results)md+=`### ${r.point.id} ${r.point.name}\n\nWGS84: ${r.point.lon}, ${r.point.lat}\n\n${explanation(r)}\n\n`;md+=`## 计时\n\n${p.task.elapsedSeconds===null?'未开始计时':`系统条件完整任务耗时 ${p.task.elapsedSeconds.toFixed(1)} 秒；${p.task.timeout?'已超过25分钟上限':'未超过25分钟上限'}`}。\n\n## 数据限制与许可\n\n${p.limitations.join('；')}。\n\n校验值：${meta.dataSha256}\n\n© OpenStreetMap contributors / ODbL 1.0\nhttps://www.openstreetmap.org/copyright\n`;download(md,'GeoInsight-初筛报告.md','text/markdown');$('export-status').textContent='初筛报告已导出；可同时导出 JSON 保存指标依据。';toast('初筛报告已导出');};
async function load(){try{[pois,meta,roads]=await Promise.all(['pois','meta','roads'].map(async name=>{const r=await fetch(`data/${name}.json`);if(!r.ok)throw new Error(`无法载入 ${name} 数据`);const x=await r.json();return name==='roads'?x.features:x;}));state.ready=true;$('loading').hidden=true;$('snapshot').textContent=meta.sourceTimestamp.slice(0,10);$('legend').innerHTML=Object.values(CATEGORIES).map(c=>`<span><i style="background:${c.color}"></i>${c.label}</span>`).join('');update();fit();registerWebMCP();}catch(err){$('loading').hidden=true;$('load-error').hidden=false;$('load-error').textContent=`空间数据加载失败，请刷新后重试。${err.message}`;for(const b of document.querySelectorAll('button'))b.disabled=true;}}
function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_candidate_analysis',description:'读取当前三个候选区域、统一口径指标及来源依据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('不接受额外参数');return payload();}},{name:'set_candidate_point',description:'更新指定候选点的名称及 WGS84 坐标，并重新计算页面比较结果；若正在计时，会取消该次任务。',inputSchema:{type:'object',properties:{id:{type:'string',enum:['A','B','C']},name:{type:'string',minLength:1,maxLength:60},longitude:{type:'number'},latitude:{type:'number'}},required:['id','name','longitude','latitude'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['id','name','longitude','latitude'].includes(k))||!['A','B','C'].includes(input.id))throw new Error('候选点ID或参数无效');validatePoint({name:input.name,lon:input.longitude,lat:input.latitude});if(input.longitude<116.1||input.longitude>116.75||input.latitude<39.65||input.latitude>40.18)throw new Error('选点超出研究窗口');state.active=state.points.findIndex(p=>p.id===input.id);setPoint({name:input.name,lon:input.longitude,lat:input.latitude});return{candidate:state.points[state.active],counts:state.results[state.active].counts};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
// Read-only inspection hook also permits reproducible local QA without relying on the WebMCP proposal.
window.GeoInsight={readAnalysis:()=>state.ready?payload():null,ready:()=>state.ready};
load();
